// client/src/pages/CouponCenter.jsx
import React, { useEffect, useState, useRef } from 'react';
import { getMyCoupons, redeemCoupon } from '../api/couponApi';
import RouletteWheel from '../components/RouletteWheel';

function CouponCenter() {
  const [coupons, setCoupons] = useState([]);
  const [rewards, setRewards] = useState([]);
  const [showConfetti, setShowConfetti] = useState(false);
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotationAngle, setRotationAngle] = useState(0);
  const [spinResult, setSpinResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const containerRef = useRef(null);
  const [mousePos, setMousePos] = useState({ x: 50, y: 50 });

  useEffect(() => {
    const handleMouseMove = (e) => {
      if (containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        setMousePos({
          x: ((e.clientX - rect.left) / rect.width) * 100,
          y: ((e.clientY - rect.top) / rect.height) * 100
        });
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        let apiCoupons = [];
        try {
          const couponRes = await getMyCoupons();
          apiCoupons = couponRes.data || [];
        } catch (e) {
          console.log('API 쿠폰 불러오기 실패, localStorage 사용');
        }
        const savedCoupons = JSON.parse(localStorage.getItem('my_coupons') || '[]');
        const allCoupons = [...savedCoupons, ...apiCoupons];
        const uniqueCoupons = allCoupons.filter((coupon, index, self) =>
          index === self.findIndex((c) => c._id === coupon._id)
        );
        setCoupons(uniqueCoupons);
        const defaultRewards = [
          { name: '이니스프리 10% OFF', type: 'COUPON', probability: 8, brand: 'Innisfree', url: 'https://www.innisfree.com' },
          { name: '에뛰드 10% OFF', type: 'COUPON', probability: 8, brand: 'Etude', url: 'https://www.etude.com' },
          { name: '토니모리 10% OFF', type: 'COUPON', probability: 6, brand: 'TonyMoly', url: 'https://www.tonymoly.com' },
          { name: '미샤 10% OFF', type: 'COUPON', probability: 5, brand: 'Missha', url: 'https://www.missha.com' },
          { name: '클리오 10% OFF', type: 'COUPON', probability: 6, brand: 'Clio', url: 'https://www.cliocosmetic.com' },
          { name: '롬앤 10% OFF', type: 'COUPON', probability: 7, brand: "Rom&nd", url: 'https://romand.co.kr' },
          { name: '라네즈 10% OFF', type: 'COUPON', probability: 5, brand: 'Laneige', url: 'https://www.laneige.com' },
          { name: '올리브영 10% OFF', type: 'COUPON', probability: 7, brand: 'OliveYoung', url: 'https://www.oliveyoung.co.kr' },
          { name: '10 포인트', type: 'POINTS', probability: 10 },
          { name: '50 포인트', type: 'POINTS', probability: 8 },
          { name: '꽝', type: 'NONE', probability: 30 },
        ];
        setRewards(defaultRewards);
      } catch (err) {
        console.error(err);
        setRewards([]);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const weightedPick = (items) => {
    const total = items.reduce((s, it) => s + (it.probability || 0), 0);
    const r = Math.random() * total;
    let acc = 0;
    for (const it of items) {
      acc += (it.probability || 0);
      if (r <= acc) return it;
    }
    return items[items.length - 1];
  };

  const handleSpin = () => {
    if (isSpinning || rewards.length === 0) return;
    setIsSpinning(true);
    setSpinResult(null);
    const resReward = weightedPick(rewards);
    setSpinResult({ success: true, reward: resReward });
    const totalSegments = rewards.length;
    const segmentAngle = 360 / totalSegments;
    const rewardIndex = rewards.findIndex(r => r.name === resReward.name);
    const segmentCenterAngle = (rewardIndex + 0.5) * segmentAngle;
    const spins = 5;
    const stopAngle = spins * 360 + (-90 - segmentCenterAngle);
    setRotationAngle(prev => prev + stopAngle);
    setTimeout(() => {
      setIsSpinning(false);
      setShowConfetti(true);
      setTimeout(() => setShowConfetti(false), 3000);
      if (resReward.type === 'COUPON') {
        const couponCode = resReward.brand.toUpperCase() + '-' + Math.random().toString(36).slice(2,8).toUpperCase();
        const newCoupon = { 
          _id: 'coupon-' + Date.now(), 
          brand: resReward.brand, 
          name: resReward.name,
          code: couponCode, 
          discount: resReward.name.match(/(\d+%)/)?.[0] || '10%', 
          url: resReward.url,
          redeemed: false,
          createdAt: new Date().toISOString()
        };
        const savedCoupons = JSON.parse(localStorage.getItem('my_coupons') || '[]');
        savedCoupons.unshift(newCoupon);
        localStorage.setItem('my_coupons', JSON.stringify(savedCoupons));
        setCoupons(prev => [newCoupon, ...prev]);
        alert(`🎉 당첨: ${resReward.name}\n쿠폰코드: ${couponCode}\n쿠폰이 쿠폰함에 추가되었습니다!`);
      } else if (resReward.type === 'POINTS') {
        alert(`🎉 당첨: ${resReward.name} — 포인트가 지급되었습니다.`);
      } else {
        alert('아쉽지만 다음 기회에!');
      }
    }, 4200);
  };

  const handleCopy = (code) => {
    try {
      navigator.clipboard.writeText(code);
      alert('쿠폰 코드가 복사되었습니다.');
    } catch (e) {
      alert('클립보드 복사에 실패했습니다.');
    }
  };

  const handleRedeem = async (id) => {
    try {
      const res = await redeemCoupon(id);
      setCoupons(prev => prev.map(c => (c._id === id ? res.data : c)));
      alert('쿠폰 사용 처리되었습니다.');
    } catch (err) {
      alert('사용 실패: ' + (err.response?.data?.message || err.message));
    }
  };

  return (
    <div 
      ref={containerRef}
      className="page-enter" 
      style={{ 
        padding: '40px 20px 80px', 
        background: `radial-gradient(circle at ${mousePos.x}% ${mousePos.y}%, rgba(255,77,136,0.08) 0%, transparent 50%), linear-gradient(180deg, #fff 0%, #fff5f7 30%, #faf5ff 70%, #f0f9ff 100%)`, 
        minHeight: '100vh', 
        position: 'relative',
        transition: 'background 0.3s ease'
      }}>
      <style>{`
        @keyframes float { 0%, 100% { transform: translateY(0px) rotate(0deg); } 50% { transform: translateY(-15px) rotate(5deg); } }
        @keyframes pulse { 0%, 100% { transform: scale(1); opacity: 0.8; } 50% { transform: scale(1.1); opacity: 1; } }
        @keyframes shimmer { 0% { background-position: -200% center; } 100% { background-position: 200% center; } }
        @keyframes slideUp { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes glow { 0%, 100% { box-shadow: 0 0 20px rgba(255,77,136,0.3); } 50% { box-shadow: 0 0 40px rgba(255,77,136,0.5); } }
        @keyframes bounce { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @keyframes confettiFall { to { transform: translateY(100vh) rotate(720deg); opacity: 0; } }
        .coupon-card:hover { transform: translateY(-5px) scale(1.02); box-shadow: 0 20px 50px rgba(255,77,136,0.2); }
        .reward-item:hover { transform: translateX(5px); background: linear-gradient(135deg, rgba(255,77,136,0.15), rgba(168,85,247,0.15)) !important; }
      `}</style>

      <div style={{ position: 'fixed', top: 100, left: '5%', fontSize: 36, animation: 'float 6s ease-in-out infinite', opacity: 0.4, pointerEvents: 'none' }}>🎫</div>
      <div style={{ position: 'fixed', top: 200, right: '10%', fontSize: 28, animation: 'float 5s ease-in-out infinite 1s', opacity: 0.35, pointerEvents: 'none' }}>✨</div>
      <div style={{ position: 'fixed', bottom: 150, left: '8%', fontSize: 24, animation: 'float 7s ease-in-out infinite 2s', opacity: 0.3, pointerEvents: 'none' }}>🎁</div>
      <div style={{ position: 'fixed', bottom: 250, right: '5%', fontSize: 32, animation: 'float 4s ease-in-out infinite 0.5s', opacity: 0.4, pointerEvents: 'none' }}>💖</div>

      {showConfetti && (
        <>
          {[...Array(60)].map((_, i) => (
            <div key={i} className="confetti" style={{ 
              position: 'fixed', left: `${Math.random() * 100}%`, top: '-10px',
              width: `${Math.random() * 10 + 5}px`, height: `${Math.random() * 10 + 5}px`,
              background: ['#ff4d88', '#ff2d6f', '#ffd7e4', '#ffb3d1', '#a855f7', '#ffd700'][Math.floor(Math.random() * 6)],
              borderRadius: Math.random() > 0.5 ? '50%' : '2px',
              animation: `confettiFall ${Math.random() * 2 + 2}s linear forwards`,
              animationDelay: `${Math.random() * 0.5}s`, zIndex: 1000
            }}></div>
          ))}
        </>
      )}
      
      <div style={{ maxWidth: 1200, margin: '0 auto', position: 'relative', zIndex: 1 }}>
        <div style={{ textAlign: 'center', marginBottom: 40, animation: 'slideUp 0.6s ease-out' }}>
          <h2 style={{ 
            fontSize: 40, fontWeight: 900, marginBottom: 12,
            background: 'linear-gradient(135deg, #ff4d88 0%, #ff6b9d 30%, #a855f7 70%, #3b82f6 100%)',
            backgroundSize: '200% auto', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent',
            animation: 'shimmer 3s linear infinite'
          }}>🎫 브랜드 룰렛 & 쿠폰센터</h2>
          <p style={{ color: '#666', fontSize: 16, fontWeight: 500 }}>룰렛에 참여하여 제휴 브랜드의 쿠폰 또는 포인트를 즉시 획득하세요! ✨</p>
        </div>

        <div style={{ 
          background: 'rgba(255,255,255,0.85)', backdropFilter: 'blur(20px)', borderRadius: 28, 
          padding: '28px 32px', marginBottom: 32, display: 'flex', alignItems: 'center', gap: 28,
          border: '1px solid rgba(255,255,255,0.5)', boxShadow: '0 20px 60px rgba(255,77,136,0.12)',
          animation: 'slideUp 0.6s ease-out 0.1s both', position: 'relative', overflow: 'hidden'
        }}>
          <div style={{ position: 'absolute', top: -50, right: -50, width: 150, height: 150, background: 'radial-gradient(circle, rgba(255,77,136,0.1) 0%, transparent 70%)', borderRadius: '50%' }} />
          <div style={{ display: 'flex', gap: 14 }}>
            {['/images/립스틱리뷰.jpg', '/images/비타민세럼리뷰.jpg', '/images/마스크팩리뷰.jpg'].map((img, idx) => (
              <div key={idx} style={{ width: 90, height: 90, borderRadius: 16, overflow: 'hidden', boxShadow: '0 8px 24px rgba(0,0,0,0.12)', border: '3px solid #fff', animation: `float ${4 + idx}s ease-in-out infinite ${idx * 0.3}s` }}>
                <img src={img} alt={`리워드${idx + 1}`} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              </div>
            ))}
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 800, fontSize: 20, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 10 }}>
              <span style={{ animation: 'bounce 2s ease-in-out infinite' }}>🎁</span>오늘의 리워드 미리보기
            </div>
            <div style={{ color: '#666', fontSize: 14, marginBottom: 12, lineHeight: 1.6 }}>MUSINSA 15% OFF, Innisfree 샘플킷, Olive Young 20% 할인권 등 다양한 혜택!</div>
            <div style={{ display: 'flex', gap: 10 }}>
              {[{ label: '💄 뷰티', bg: 'linear-gradient(135deg, #ff4d88, #ff6b9d)' }, { label: '👗 패션', bg: 'linear-gradient(135deg, #3b82f6, #60a5fa)' }, { label: '🛍️ 쇼핑', bg: 'linear-gradient(135deg, #10b981, #34d399)' }].map((tag, idx) => (
                <span key={idx} style={{ background: tag.bg, color: '#fff', padding: '6px 14px', borderRadius: 20, fontSize: 12, fontWeight: 700, boxShadow: '0 4px 12px rgba(0,0,0,0.15)' }}>{tag.label}</span>
              ))}
            </div>
          </div>
          <div style={{ textAlign: 'center', background: 'linear-gradient(135deg, rgba(255,77,136,0.1), rgba(168,85,247,0.1))', borderRadius: 20, padding: '20px 28px' }}>
            <div style={{ fontSize: 40, fontWeight: 900, background: 'linear-gradient(135deg, #ff4d88, #a855f7)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>7</div>
            <div style={{ fontSize: 12, color: '#888', fontWeight: 600 }}>가지 리워드</div>
          </div>
        </div>

        <div style={{ display: 'flex', gap: 28, alignItems: 'flex-start' }}>
          <div style={{ flex: 1, background: 'rgba(255,255,255,0.85)', backdropFilter: 'blur(20px)', borderRadius: 28, padding: '48px', boxShadow: '0 20px 60px rgba(0,0,0,0.08)', border: '1px solid rgba(255,255,255,0.5)', overflow: 'hidden', animation: 'slideUp 0.6s ease-out 0.2s both', minHeight: 580 }}>
            <div style={{ display: 'flex', gap: 48, alignItems: 'center', justifyContent: 'center' }}>
              <div style={{ width: 500, minWidth: 500, display: 'flex', justifyContent: 'center', alignItems: 'center', background: 'radial-gradient(circle, rgba(255,77,136,0.08) 0%, transparent 70%)', borderRadius: '50%', padding: 10, animation: isSpinning ? 'glow 0.5s ease-in-out infinite' : 'none' }}>
                <RouletteWheel rewards={rewards} rotationAngle={rotationAngle} isSpinning={isSpinning} spinResult={spinResult} />
              </div>
              <div style={{ flex: 1 }}>
                <h3 style={{ marginTop: 0, fontSize: 24, fontWeight: 800, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 10 }}>
                  <span style={{ animation: 'bounce 2s ease-in-out infinite' }}>🎡</span>오늘의 브랜드 룰렛
                </h3>
                <p style={{ color: '#888', fontSize: 14, marginBottom: 20 }}>매일 1회 무료 참여 · 추가 참여는 포인트로 결제</p>
                <div style={{ marginBottom: 16 }}>
                  <button 
                    onClick={handleSpin} 
                    disabled={isSpinning} 
                    style={{ 
                      background: isSpinning ? 'linear-gradient(135deg, #ccc, #aaa)' : 'linear-gradient(135deg, #ff4d88, #ff6b9d, #a855f7)',
                      backgroundSize: '200% auto', color: '#fff', border: 'none', padding: '16px 40px', borderRadius: 20, 
                      fontWeight: 800, fontSize: 16, boxShadow: isSpinning ? 'none' : '0 12px 32px rgba(255,77,136,0.4)', 
                      cursor: isSpinning ? 'not-allowed' : 'pointer', transition: 'all 0.3s ease',
                      animation: isSpinning ? 'none' : 'glow 2s ease-in-out infinite'
                    }}
                    onMouseOver={(e) => { if (!isSpinning) { e.currentTarget.style.transform = 'translateY(-3px) scale(1.05)'; e.currentTarget.style.backgroundPosition = 'right center'; } }}
                    onMouseOut={(e) => { e.currentTarget.style.transform = 'translateY(0) scale(1)'; e.currentTarget.style.backgroundPosition = 'left center'; }}
                  >{isSpinning ? '🎡 돌아가는 중...' : '🎯 START'}</button>
                </div>
                {spinResult && (
                  <div style={{ padding: '16px 20px', borderRadius: 16, background: 'linear-gradient(135deg, rgba(168,85,247,0.15), rgba(255,77,136,0.15))', border: '1px solid rgba(168,85,247,0.3)', animation: 'slideUp 0.4s ease-out' }}>
                    <div style={{ fontSize: 13, color: '#888', marginBottom: 4 }}>🎉 당첨 결과</div>
                    <div style={{ fontSize: 20, fontWeight: 800, background: 'linear-gradient(135deg, #ff4d88, #a855f7)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>{spinResult.reward.name}</div>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div style={{ width: 380, animation: 'slideUp 0.6s ease-out 0.3s both' }}>
            <div style={{ background: 'rgba(255,255,255,0.85)', backdropFilter: 'blur(20px)', borderRadius: 24, padding: '24px', boxShadow: '0 16px 48px rgba(0,0,0,0.06)', border: '1px solid rgba(255,255,255,0.5)', marginBottom: 20 }}>
              <h4 style={{ marginTop: 0, fontSize: 18, fontWeight: 800, marginBottom: 16, display: 'flex', alignItems: 'center', gap: 8 }}><span>🎁</span> 획득 가능한 쿠폰</h4>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                {rewards && rewards.filter(r => r.type === 'COUPON').map((r, i) => (
                  <div key={i} className="reward-item" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '14px 16px', borderRadius: 16, background: i % 2 === 0 ? 'linear-gradient(135deg, rgba(255,77,136,0.08), rgba(255,77,136,0.04))' : 'linear-gradient(135deg, rgba(168,85,247,0.08), rgba(168,85,247,0.04))', transition: 'all 0.3s ease', cursor: 'default' }}>
                    <div>
                      <div style={{ fontWeight: 800, fontSize: 15, color: '#333' }}>{r.name.split(' ')[0]}</div>
                      <div style={{ color: '#888', fontSize: 13 }}>{r.name}</div>
                    </div>
                    <div style={{ textAlign: 'right', background: 'linear-gradient(135deg, #ff4d88, #a855f7)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
                      <div style={{ fontWeight: 900, fontSize: 18 }}>{r.probability}%</div>
                      <div style={{ fontSize: 11, color: '#888', WebkitTextFillColor: '#888' }}>확률</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div style={{ background: 'rgba(255,255,255,0.85)', backdropFilter: 'blur(20px)', borderRadius: 24, padding: '24px', boxShadow: '0 16px 48px rgba(0,0,0,0.06)', border: '1px solid rgba(255,255,255,0.5)' }}>
              <h4 style={{ marginTop: 0, fontSize: 18, fontWeight: 800, marginBottom: 16, display: 'flex', alignItems: 'center', gap: 8 }}><span style={{ animation: 'bounce 2s ease-in-out infinite' }}>🎫</span> 내 쿠폰함</h4>
              {coupons.length === 0 ? (
                <div style={{ textAlign: 'center', padding: '32px 20px', background: 'rgba(255,77,136,0.05)', borderRadius: 16 }}>
                  <div style={{ fontSize: 40, marginBottom: 12, animation: 'float 4s ease-in-out infinite' }}>🎫</div>
                  <div style={{ color: '#888', fontSize: 14 }}>현재 보유한 쿠폰이 없습니다.</div>
                  <div style={{ color: '#aaa', fontSize: 13, marginTop: 4 }}>룰렛을 돌려 쿠폰을 획득해보세요!</div>
                </div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                  {coupons.map((c, idx) => (
                    <div key={c._id} className="coupon-card" style={{ padding: '16px', borderRadius: 16, background: 'linear-gradient(135deg, #fff 0%, #fff5f7 100%)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', border: '2px dashed rgba(255,77,136,0.2)', transition: 'all 0.3s ease', animation: `slideUp 0.4s ease-out ${idx * 0.1}s both` }}>
                      <div>
                        <div style={{ fontWeight: 800, fontSize: 15, color: '#ff4d88' }}>{c.brand}</div>
                        <div style={{ fontSize: 12, color: '#666', marginTop: 2 }}>{c.name || c.discount}</div>
                        <div style={{ color: '#666', fontSize: 12, marginTop: 4, fontFamily: 'monospace', background: 'rgba(0,0,0,0.03)', padding: '4px 8px', borderRadius: 6 }}>{c.code}</div>
                      </div>
                      <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                        {!c.redeemed ? (
                          <button 
                            onClick={() => { 
                              navigator.clipboard.writeText(c.code);
                              alert(`✅ 쿠폰 코드가 복사되었습니다!\n\n코드: ${c.code}\n\n${c.brand} 홈페이지로 이동합니다.`);
                              if (c.url) window.open(c.url, '_blank');
                              setCoupons(prev => prev.map(coupon => coupon._id === c._id ? {...coupon, redeemed: true} : coupon));
                            }} 
                            style={{ padding: '10px 16px', borderRadius: 12, background: 'linear-gradient(135deg, #ff4d88, #ff6b9d)', color: '#fff', border: 'none', fontWeight: 700, fontSize: 12, cursor: 'pointer', boxShadow: '0 4px 12px rgba(255,77,136,0.3)', transition: 'all 0.2s ease' }}
                            onMouseOver={e => e.currentTarget.style.transform = 'scale(1.05)'}
                            onMouseOut={e => e.currentTarget.style.transform = 'scale(1)'}
                          >사용</button>
                        ) : (
                          <span style={{ color: '#10b981', fontWeight: 700, fontSize: 13, display: 'flex', alignItems: 'center', gap: 4 }}>✓ 사용됨</span>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default CouponCenter;
